bool CoreTenantResetPlans::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("tenant_id"))
    {
        if(!validJsonOfField(1, "tenant_id", pJson["tenant_id"], err, true))
            return false;
    }

    else
    {
        err="The tenant_id column cannot be null";
        return false;
    }

    if(pJson.isMember("created_by_user_id"))
    {
        if(!validJsonOfField(2, "created_by_user_id", pJson["created_by_user_id"], err, true))
            return false;
    }

    else
    {
        err="The created_by_user_id column cannot be null";
        return false;
    }

    if(pJson.isMember("requested_tables"))
    {
        if(!validJsonOfField(3, "requested_tables", pJson["requested_tables"], err, true))
            return false;
    }

    if(pJson.isMember("snapshot"))
    {
        if(!validJsonOfField(4, "snapshot", pJson["snapshot"], err, true))
            return false;
    }

    else
    {
        err="The snapshot column cannot be null";
        return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(5, "created_at", pJson["created_at"], err, true))
            return false;
    }

    if(pJson.isMember("expires_at"))
    {
        if(!validJsonOfField(6, "expires_at", pJson["expires_at"], err, true))
            return false;
    }

    if(pJson.isMember("used_at"))
    {
        if(!validJsonOfField(7, "used_at", pJson["used_at"], err, true))
            return false;
    }

    if(pJson.isMember("is_deleted"))
    {
        if(!validJsonOfField(8, "is_deleted", pJson["is_deleted"], err, true))
            return false;
    }

    return true;
}
